// 2845. Count of Interesting Subarrays (Medium).
// Specification: https://leetcode.com/problems/count-of-interesting-subarrays/description/
function solve(nums, modulo, k) {
  const cnt = new Map([[0, 1]]);
  let s = 0; let ans = 0;
  for (const x of nums) {
