    const sm = ((s % modulo) + modulo) % modulo;
    const target = ((sm - k) % modulo + modulo) % modulo;
    ans += cnt.get(target) || 0;
    cnt.set(sm, (cnt.get(sm) || 0) + 1);
  }
  return ans;
}
